// Para mudar a marca, mude o SVG na raiz do repositório e rode, de dentro de app/:
//   dart run tool/gen_marca.dart
//
// ignore_for_file: lines_longer_than_80_chars

/// Uma camada de cor de um vetor da marca.
///
/// [papel] é o nome do papel em `BichuCores`, nunca um valor de cor:
/// quem pinta resolve pelo tema. [d] é o atributo `d` do SVG de origem,
/// com os comandos `M`, `C` e `Z` — os únicos que o derivador emite.
class CamadaDaMarca {
  const CamadaDaMarca(this.papel, this.d);

  final String papel;
  final String d;
}

/// Um vetor da marca, como o SVG de origem o declara.
class VetorDaMarca {
  const VetorDaMarca({
    required this.arquivo,
    required this.origemX,
    required this.origemY,
    required this.largura,
    required this.altura,
    required this.pisoPx,
    required this.camadas,
  });

  /// O nome do arquivo em `design/marca/vetor/`.
  final String arquivo;

  /// Canto superior esquerdo do `viewBox`. Não é sempre a origem:
  /// a variante reduzida foi reemoldurada e nasce em coordenada negativa.
  final double origemX;
  final double origemY;

  /// Largura e altura do `viewBox`.
  final double largura;
  final double altura;

  /// Piso de redução da §3.10 do design system, na maior dimensão.
  final double pisoPx;

  final List<CamadaDaMarca> camadas;
}

